import {pick,STATUS,simulate} from './engine.js';
import {language} from '../i18n.js';
import {escapeHTML as e} from '../explorer-views.js';
import {bank} from '../v3/engine.js';
const L=(en,zh,ms)=>pick([en,zh,ms],language),P=x=>pick(x,language);
const sourceDate=value=>{const d=new Date(value);return Number.isFinite(d.valueOf())?new Intl.DateTimeFormat(language,{year:'numeric',month:'short',day:'numeric',timeZone:'Asia/Kuala_Lumpur'}).format(d):String(value||'');};
const categories={grow:['Growth & integration','增长与整合','Pertumbuhan & integrasi'],automate:['Routine automation','重复性自动化','Automasi rutin'],human:['Human judgment','人类判断','Pertimbangan manusia'],assist:['AI assistance','AI 辅助','Bantuan AI'],context:['Context matters','依情境而定','Mengikut konteks']};
export function executiveSummary(a){
 const role=a.roles[0],track=bank.tracks.find(t=>t.id===a.direction),imp=role.aiImpact,total=imp.tasks.length;
 const headline={'ai-growth':['AI moves this work toward building and integrating systems.','AI 让这份工作更侧重构建与整合系统。','AI mengalih kerja ini ke arah membina dan mengintegrasi sistem.'],'automation-pressure':['Routine tasks may change. Judgment becomes a useful place to explore.','重复性任务可能改变，判断力值得重点探索。','Tugas rutin mungkin berubah. Pertimbangan wajar diterokai.'],'limited-change':['Human judgment remains central to the recorded tasks.','在已记录的任务中，人类判断仍然关键。','Pertimbangan manusia kekal utama dalam tugas direkodkan.'],restructuring:['AI changes the mix of tasks, and what is worth practising.','AI 正在改变任务组合，也改变值得练习的重点。','AI mengubah gabungan tugas dan keutamaan latihan.']};
 return `<section class="release-summary" aria-labelledby="release-conclusion"><div class="release-summary-top"><span class="an-eyebrow">${L('YOUR CAREER BRIEF','你的职业简报','RINGKASAN KERJAYA ANDA')}</span><span>${e(P(track.label))}</span></div><h1 id="release-conclusion" tabindex="-1">${e(P(headline[imp.path]||headline.restructuring))}</h1><p class="release-context">${e(P(role.title))} · ${L('A first direction to investigate, not a suitability verdict.','一个优先调查的方向，不是适合度定论。','Arah awal untuk disiasat, bukan keputusan kesesuaian.')}</p><div class="release-analysis"><div><h2>${L('How the work may change','工作可能如何变化','Cara kerja mungkin berubah')}</h2><div class="release-task-bar" role="img" aria-label="${L('Task category counts, not probabilities','任务类别计数，不是概率','Bilangan kategori tugas, bukan kebarangkalian')}">${Object.entries(imp.counts).filter(([,n])=>n).map(([k,n])=>`<span class="task-${k}" style="flex:${n}" title="${e(P(categories[k]))}: ${n}"></span>`).join('')}</div><ul class="release-task-legend">${Object.entries(imp.counts).filter(([,n])=>n).map(([k,n])=>`<li><i class="task-${k}"></i><span>${e(P(categories[k]))}</span><strong>${n}</strong></li>`).join('')}</ul><details><summary>${L('Read the underlying tasks','查看具体任务','Baca tugas asas')} · ${total}</summary><ul>${imp.tasks.map(t=>`<li><small>${e(P(categories[t.category]))}</small><p lang="en">${e(t.label)}</p></li>`).join('')}</ul></details><p class="release-source">${L('Team classification of official tasks; not a forecast.','对官方任务的团队分类，不是预测。','Pengelasan pasukan bagi tugas rasmi; bukan ramalan。')} <a href="${e(role.source?.url||'https://www.onetonline.org/')}" target="_blank" rel="noopener noreferrer">O*NET ↗</a> · ${e(sourceDate(role.source?.verified_at)||a.knowledgeVersion)}</p></div><div class="release-personal"><span class="an-eyebrow">${L('YOUR POSITION','你的起点','KEDUDUKAN ANDA')}</span><h2>${e(P(a.personal.phaseLabel))}</h2><p>${e(P(a.personal.next.why))}</p><dl><div><dt>${L('Task interest','任务兴趣','Minat tugas')}</dt><dd>${e(P(a.personal.preference))}</dd></div><div><dt>${L('Next requirement to check','下一项待核验要求','Keperluan seterusnya untuk disemak')}</dt><dd lang="en">${e(role.requirements[0]?.label||P(role.project))}</dd></div></dl><button class="button primary" data-combined-action="plan:${e(role.id)}">${L('Build my next experiment','规划下一次实践','Bina eksperimen seterusnya')} ↗</button></div></div><div class="release-summary-foot"><button class="text-button" data-combined-action="page:galaxy">${L('Explore my career galaxy','探索我的职业星图','Terokai galaksi kerjaya saya')} ↗</button><span>${L('Self-reported evidence · no verified capability score','自述证据 · 不生成虚假的能力分数','Bukti kendiri · tiada skor kebolehan disahkan')}</span></div></section>`;
}
export function scenarioChart(a,scenario){
 const baseline=simulate(a,{targetCareer:scenario.roleId});
 const labels=[L('Baseline','基础计划','Asas'),L('This scenario','本次情景','Senario ini')];
 const max=Math.max(baseline.stages.at(-1).endWeek||0,scenario.stages.at(-1).endWeek||0,1);
 return `<section class="release-scenario-chart" aria-live="polite"><span class="an-eyebrow">${L('MILESTONE COMPARISON','里程碑对比','PERBANDINGAN PENCAPAIAN')}</span><h2>${L('See what your time changes.','看见时间如何改变计划。','Lihat perubahan daripada masa anda.')}</h2><p>${L('Planned weeks to each review stage. Estimates describe effort, not success.','各复核阶段的计划周数。估计描述投入，不预测成功。','Minggu dirancang untuk setiap peringkat semakan. Anggaran usaha, bukan kejayaan.')}</p>${[baseline,scenario].map((s,i)=>`<div class="release-scenario-row"><strong>${labels[i]}<small>${s.weeklyHours} ${L('h/week','小时／周','jam/minggu')}</small></strong><div class="release-scenario-track">${s.stages.map((stage,j)=>`<div class="release-milestone milestone-${j}" style="width:${stage.endWeek===null?0:100*stage.endWeek/max}%"><span>${e(P(stage.title))} · ${stage.endWeek??'—'}</span></div>`).reverse().join('')}</div></div>`).join('')}<div class="release-scenario-accessible">${scenario.stages.map(stage=>`<span>${e(P(stage.title))}: ${stage.endWeek===null?L('Set a time budget to schedule','设定时间预算后安排','Tetapkan bajet masa'):L('week','第几周','minggu')+' '+stage.endWeek}</span>`).join('')}</div></section>`;
}
